import type { ReportTable } from "@/types/records";
import { cleanParams } from "@/lib/utils/query";
import { baseApi } from "../baseApi";

/** Government forms, monitoring views and the audit trail, generated by the API as tables. */
export const reportFormsApi = baseApi.injectEndpoints({
  endpoints: (build) => ({
    getReportForm: build.query<ReportTable, { code: string; filters: Record<string, string | undefined> }>({
      query: ({ code, filters }) => ({ url: `/reports/forms/${code}`, params: cleanParams(filters) }),
      providesTags: ["Report"],
    }),
  }),
});

export const { useGetReportFormQuery } = reportFormsApi;
